function makeAssistantMessage(text: string): Message {
	return {
		role: "assistant",
		content: [{ type: "text", text }],
		api: "anthropic-messages",
		provider: "anthropic",
		model: "test",
		usage: {
			input: 1,
			output: 1,
			cacheRead: 0,
			cacheWrite: 0,
			totalTokens: 2,
			cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, total: 0 },
		},
		stopReason: "stop",
		timestamp: Date.now(),
	};
}

describe("SessionManager new-session default", () => {
	let testDir: string;

	beforeEach(() => {
		testDir = join(tmpdir(), `pi-session-default-test-${Date.now()}-${Math.random().toString(36).slice(2)}`);
	});

	afterEach(() => {
		if (existsSync(testDir)) {
			rmSync(testDir, { recursive: true });
		}
	});

	describe("getSessionDefaultFromHeader", () => {
		it("returns null for a null header", () => {
			expect(getSessionDefaultFromHeader(null)).toBeNull();
		});

		it("returns null for an empty header object", () => {
			const header: SessionHeader = {
				type: "session",
				id: "test",
				timestamp: new Date().toISOString(),
				cwd: "/tmp",
			};
			expect(getSessionDefaultFromHeader(header)).toEqual({ model: undefined, thinkingLevel: undefined });
		});

		it("returns the model and thinking level when present", () => {
			const header: SessionHeader = {
				type: "session",
				id: "test",
				timestamp: new Date().toISOString(),
				cwd: "/tmp",
				model: { provider: "anthropic", modelId: "claude-sonnet-4-5" },
				thinkingLevel: "high",
			};
			expect(getSessionDefaultFromHeader(header)).toEqual({
				model: { provider: "anthropic", modelId: "claude-sonnet-4-5" },
				thinkingLevel: "high",
			});
		});

		it("returns partial preferences when only one field is set", () => {
			const header: SessionHeader = {
				type: "session",
				id: "test",
				timestamp: new Date().toISOString(),
				cwd: "/tmp",
				model: { provider: "openai", modelId: "gpt-5" },
			};
			expect(getSessionDefaultFromHeader(header)).toEqual({
				model: { provider: "openai", modelId: "gpt-5" },
				thinkingLevel: undefined,
			});
		});
	});

	describe("setSessionDefault", () => {
		it("writes the model to the in-memory header", () => {
			const session = SessionManager.inMemory();
			session.newSession();

			session.setSessionDefault({
				model: { provider: "anthropic", modelId: "claude-sonnet-4-5" },
			});

			const header = session.getHeader();
			expect(header).not.toBeNull();
			expect(header?.model).toEqual({ provider: "anthropic", modelId: "claude-sonnet-4-5" });
		});

		it("persists the model to the session file on disk", () => {
			const session = SessionManager.inMemory();
			const newPath = session.newSession();
			expect(newPath).toBeUndefined(); // in-memory sessions do not get a file

			// For a real file, use SessionManager.create and a non-persist file
			const real = SessionManager.create(testDir, testDir, { id: "test-id" });
			real.setSessionDefault({
				model: { provider: "openai", modelId: "gpt-5" },
			});

			const realFile = real.getSessionFile();
			expect(realFile).toBeDefined();
			expect(existsSync(realFile as string)).toBe(true);

			const firstLine = readFileSync(realFile as string, "utf-8").split("\n")[0];
			const header = JSON.parse(firstLine) as SessionHeader;
			expect(header.model).toEqual({ provider: "openai", modelId: "gpt-5" });
		});

		it("does not break the first flush after creating the file on a fresh session", () => {
			// Regression test: setSessionDefault() rewrites (and thereby creates)
			// the session file before the first assistant message. The rewrite
			// must mark the session as flushed, otherwise _persist() later tries
			// to exclusively create the existing file and throws EEXIST.
			const real = SessionManager.create(testDir, testDir);
			real.setSessionDefault({
				model: { provider: "openai", modelId: "gpt-5" },
			});

			const realFile = real.getSessionFile();
			expect(realFile).toBeDefined();
			expect(existsSync(realFile as string)).toBe(true);

			expect(() => real.appendMessage(makeAssistantMessage("hi"))).not.toThrow();

			const lines = readFileSync(realFile as string, "utf-8")
				.trim()
				.split("\n");
			expect(lines).toHaveLength(2);
			const header = JSON.parse(lines[0]) as SessionHeader;
			expect(header.type).toBe("session");
			expect(header.model).toEqual({ provider: "openai", modelId: "gpt-5" });
			const assistantEntry = JSON.parse(lines[1]) as { type: string; message: { role: string } };
			expect(assistantEntry.type).toBe("message");
			expect(assistantEntry.message.role).toBe("assistant");
		});

		it("persists entries appended after a model switch on a fresh session", () => {
			// User-reported repro: start a new session, switch the model before the
			// first assistant reply, then let the session continue. The switch
			// materializes the session file; the following entries must append to
			// it, not crash trying to re-create it (EEXIST).
			const real = SessionManager.create(testDir, testDir);
			real.appendMessage({ role: "user", content: [{ type: "text", text: "hello" }], timestamp: Date.now() });

			real.setSessionDefault({ model: { provider: "openai", modelId: "gpt-5" } });

			expect(() => real.appendMessage(makeAssistantMessage("hi"))).not.toThrow();

			const lines = readFileSync(real.getSessionFile() as string, "utf-8")
				.trim()
				.split("\n");
			expect(lines).toHaveLength(3);
		});

		it("updates an existing model on subsequent calls", () => {
			const session = SessionManager.inMemory();
			session.newSession();
			session.setSessionDefault({ model: { provider: "openai", modelId: "gpt-5" } });
			session.setSessionDefault({ model: { provider: "anthropic", modelId: "claude-haiku-4-5" } });

			expect(session.getHeader()?.model).toEqual({
				provider: "anthropic",
				modelId: "claude-haiku-4-5",
			});
		});
	});

	describe("per-session model isolation", () => {
		it("switching the model in one session leaves other sessions unchanged", () => {
			const sessionA = SessionManager.create(testDir, testDir);
			const sessionB = SessionManager.create(testDir, testDir);
			sessionB.setSessionDefault({ model: { provider: "anthropic", modelId: "claude-haiku-4-5" } });

			// Switch model in session A only.
			sessionA.setSessionDefault({ model: { provider: "openai", modelId: "gpt-5" } });

			expect(sessionA.getHeader()?.model).toEqual({ provider: "openai", modelId: "gpt-5" });
			expect(sessionB.getHeader()?.model).toEqual({ provider: "anthropic", modelId: "claude-haiku-4-5" });

			// Resuming each session restores its own model: session A continues
			// with the switched model, session B keeps the model it had.
			const reopenedA = SessionManager.open(sessionA.getSessionFile() as string);
			const reopenedB = SessionManager.open(sessionB.getSessionFile() as string);
			expect(reopenedA.getHeader()?.model).toEqual({ provider: "openai", modelId: "gpt-5" });
			expect(reopenedB.getHeader()?.model).toEqual({ provider: "anthropic", modelId: "claude-haiku-4-5" });
		});
	});

	describe("newSession with model option", () => {
		it("seeds the header with the initial model", () => {
			const session = SessionManager.inMemory();
			session.newSession({
				model: { provider: "openai", modelId: "gpt-5" },
			});

			const header = session.getHeader();
			expect(header?.model).toEqual({ provider: "openai", modelId: "gpt-5" });
		});
	});
});

import { constants as bufferConstants } from "buffer";
import { appendFileSync, closeSync, mkdirSync, openSync, readFileSync, rmSync, writeFileSync, writeSync } from "fs";
import { tmpdir } from "os";
import { join } from "path";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { findMostRecentSession, loadEntriesFromFile, SessionManager } from "../../src/core/session-manager.ts";

const HEADER_SCAN_LIMIT_BYTES = 1024 * 1024;

describe("loadEntriesFromFile", () => {
	let tempDir: string;

	beforeEach(() => {
		tempDir = join(tmpdir(), `session-test-${Date.now()}`);
		mkdirSync(tempDir, { recursive: true });
	});

	afterEach(() => {
		rmSync(tempDir, { recursive: true, force: true });
	});

	function writeSessionHeader(file: string, cwd: string, id: string, prefix = ""): void {
		writeFileSync(
			file,
			`${prefix}${JSON.stringify({
				type: "session",
				version: 3,
				id,
				timestamp: "2025-01-01T00:00:00Z",
				cwd,
			})}\n`,
		);
	}

	it("returns empty array for non-existent file", () => {
		const entries = loadEntriesFromFile(join(tempDir, "nonexistent.jsonl"));
		expect(entries).toEqual([]);
	});

	it("returns empty array for empty file", () => {
		const file = join(tempDir, "empty.jsonl");
		writeFileSync(file, "");
		expect(loadEntriesFromFile(file)).toEqual([]);
	});

	it("returns empty array for file without valid session header", () => {
		const file = join(tempDir, "no-header.jsonl");
		writeFileSync(file, '{"type":"message","id":"1"}\n');
		expect(loadEntriesFromFile(file)).toEqual([]);
	});

	it("returns empty array for malformed JSON", () => {
		const file = join(tempDir, "malformed.jsonl");
		writeFileSync(file, "not json\n");
		expect(loadEntriesFromFile(file)).toEqual([]);
	});

	it("loads valid session file", () => {
		const file = join(tempDir, "valid.jsonl");
		writeFileSync(
			file,
			'{"type":"session","id":"abc","timestamp":"2025-01-01T00:00:00Z","cwd":"/tmp"}\n' +
				'{"type":"message","id":"1","parentId":null,"timestamp":"2025-01-01T00:00:01Z","message":{"role":"user","content":"hi","timestamp":1}}\n',
		);
		const entries = loadEntriesFromFile(file);
		expect(entries).toHaveLength(2);
		expect(entries[0].type).toBe("session");
		expect(entries[1].type).toBe("message");
	});

	it("skips malformed lines but keeps valid ones", () => {
		const file = join(tempDir, "mixed.jsonl");
		writeFileSync(
			file,
			'{"type":"session","id":"abc","timestamp":"2025-01-01T00:00:00Z","cwd":"/tmp"}\n' +
				"not valid json\n" +
				'{"type":"message","id":"1","parentId":null,"timestamp":"2025-01-01T00:00:01Z","message":{"role":"user","content":"hi","timestamp":1}}\n',
		);
		const entries = loadEntriesFromFile(file);
		expect(entries).toHaveLength(2);
	});

	it("adds a newline after an unterminated valid record", () => {
		const file = join(tempDir, "unterminated.jsonl");
		const content =
			'{"type":"session","id":"abc","timestamp":"2025-01-01T00:00:00Z","cwd":"/tmp"}\n' +
			'{"type":"message","id":"1","parentId":null,"timestamp":"2025-01-01T00:00:01Z","message":{"role":"user","content":"hi","timestamp":1}}';
		writeFileSync(file, content);

		expect(loadEntriesFromFile(file)).toHaveLength(2);
		expect(readFileSync(file, "utf8")).toBe(`${content}\n`);
	});

	it("adds a newline after an unterminated malformed final fragment", () => {
		const file = join(tempDir, "malformed-tail.jsonl");
		const content =
			'{"type":"session","id":"abc","timestamp":"2025-01-01T00:00:00Z","cwd":"/tmp"}\n' + '{"type":"message"';
		writeFileSync(file, content);

		expect(loadEntriesFromFile(file)).toHaveLength(1);
		expect(readFileSync(file, "utf8")).toBe(`${content}\n`);
	});

	it("does not modify an unterminated non-session file", () => {
		const file = join(tempDir, "invalid.jsonl");
		const content = '{"type":"message","id":"1"}';
		writeFileSync(file, content);

		expect(loadEntriesFromFile(file)).toEqual([]);
		expect(readFileSync(file, "utf8")).toBe(content);
	});

	it.each([
		["leading blank lines", "\n  \n", "leading-blank"],
		["leading malformed lines", "not json\n{broken json\n", "leading-malformed"],
		["a multi-buffer header", "", "a".repeat(8192)],
	])("reads cwd from a session with %s", (_description, prefix, sessionId) => {
		const file = join(tempDir, "header.jsonl");
		const storedCwd = join(tempDir, "stored-project");
		writeSessionHeader(file, storedCwd, sessionId, prefix);

		const sessionManager = SessionManager.open(file, tempDir);
		expect(sessionManager.getSessionId()).toBe(sessionId);
		expect(sessionManager.getCwd()).toBe(storedCwd);
	});

	it("opens compatible sessions beyond the discovery scan limit", () => {
		const storedCwd = join(tempDir, "stored-project");
		const overrideCwd = join(tempDir, "override-project");
		const cases = [
			{ name: "large-header", id: "a".repeat(HEADER_SCAN_LIMIT_BYTES + 1), prefix: "" },
			{
				name: "large-prefix",
				id: "large-prefix",
				prefix: `${"x".repeat(HEADER_SCAN_LIMIT_BYTES + 1)}\n`,
			},
		];

		for (const { name, id, prefix } of cases) {
			const file = join(tempDir, `${name}.jsonl`);
			writeSessionHeader(file, storedCwd, id, prefix);
			for (const cwdOverride of [undefined, overrideCwd]) {
				const sessionManager = SessionManager.open(file, tempDir, cwdOverride);
				expect(sessionManager.getSessionId()).toBe(id);
				expect(sessionManager.getCwd()).toBe(cwdOverride ?? storedCwd);
			}
		}
	});

	it("opens session files larger than Node's max string length", () => {
		const file = join(tempDir, "large.jsonl");
		writeFileSync(
			file,
			'{"type":"session","version":3,"id":"abc","timestamp":"2025-01-01T00:00:00Z","cwd":"/tmp"}\n',
		);

		const fd = openSync(file, "r+");
		try {
			const newline = Buffer.from("\n");
			const stride = 16 * 1024 * 1024;
			for (let offset = stride; offset <= bufferConstants.MAX_STRING_LENGTH + stride; offset += stride) {
				writeSync(fd, newline, 0, newline.length, offset);
			}
		} finally {
			closeSync(fd);
		}

		appendFileSync(
			file,
			'{"type":"message","id":"1","parentId":null,"timestamp":"2025-01-01T00:00:01Z","message":{"role":"user","content":"hi","timestamp":1}}\n',
		);

		const sessionManager = SessionManager.open(file, tempDir);
		expect(sessionManager.getSessionId()).toBe("abc");
		expect(sessionManager.getEntries()).toHaveLength(1);
		expect(sessionManager.buildSessionContext().messages).toEqual([{ role: "user", content: "hi", timestamp: 1 }]);
	});
});

describe("findMostRecentSession", () => {
	let tempDir: string;

	beforeEach(() => {
		tempDir = join(tmpdir(), `session-test-${Date.now()}`);
		mkdirSync(tempDir, { recursive: true });
	});

	afterEach(() => {
		rmSync(tempDir, { recursive: true, force: true });
	});

	it("returns null for empty directory", () => {
		expect(findMostRecentSession(tempDir)).toBeNull();
	});

	it("returns null for non-existent directory", () => {
		expect(findMostRecentSession(join(tempDir, "nonexistent"))).toBeNull();
	});

	it("ignores non-jsonl files", () => {
		writeFileSync(join(tempDir, "file.txt"), "hello");
		writeFileSync(join(tempDir, "file.json"), "{}");
		expect(findMostRecentSession(tempDir)).toBeNull();
	});

	it("ignores jsonl files without valid session header", () => {
		writeFileSync(join(tempDir, "invalid.jsonl"), '{"type":"message"}\n');
		expect(findMostRecentSession(tempDir)).toBeNull();
	});

	it("returns single valid session file", () => {
		const file = join(tempDir, "session.jsonl");
		writeFileSync(file, '{"type":"session","id":"abc","timestamp":"2025-01-01T00:00:00Z","cwd":"/tmp"}\n');
		expect(findMostRecentSession(tempDir)).toBe(file);
	});

	it("returns most recently modified session", async () => {
		const file1 = join(tempDir, "older.jsonl");
		const file2 = join(tempDir, "newer.jsonl");

		writeFileSync(file1, '{"type":"session","id":"old","timestamp":"2025-01-01T00:00:00Z","cwd":"/tmp"}\n');
		// Small delay to ensure different mtime
		await new Promise((r) => setTimeout(r, 10));
		writeFileSync(file2, '{"type":"session","id":"new","timestamp":"2025-01-01T00:00:00Z","cwd":"/tmp"}\n');

		expect(findMostRecentSession(tempDir)).toBe(file2);
	});

	it("skips invalid files and returns valid one", async () => {
		const invalid = join(tempDir, "invalid.jsonl");
		const valid = join(tempDir, "valid.jsonl");

		writeFileSync(invalid, '{"type":"not-session"}\n');
		await new Promise((r) => setTimeout(r, 10));
		writeFileSync(valid, '{"type":"session","id":"abc","timestamp":"2025-01-01T00:00:00Z","cwd":"/tmp"}\n');

		expect(findMostRecentSession(tempDir)).toBe(valid);
	});

	it("skips oversized corrupt files and returns a valid session", () => {
		const invalid = join(tempDir, "oversized.jsonl");
		const valid = join(tempDir, "valid.jsonl");
		writeFileSync(invalid, "x".repeat(HEADER_SCAN_LIMIT_BYTES + 1));
		writeFileSync(valid, '{"type":"session","id":"abc","timestamp":"2025-01-01T00:00:00Z","cwd":"/tmp"}\n');

		expect(findMostRecentSession(tempDir)).toBe(valid);
	});

	it("filters most recent session by cwd", async () => {
		const projectA = join(tempDir, "project-a");
		const projectB = join(tempDir, "project-b");
		const fileA = join(tempDir, "a.jsonl");
		const fileB = join(tempDir, "b.jsonl");

		writeFileSync(
			fileA,
			`${JSON.stringify({ type: "session", id: "a", timestamp: "2025-01-01T00:00:00Z", cwd: projectA })}\n`,
		);
		await new Promise((r) => setTimeout(r, 10));
		writeFileSync(
			fileB,
			`${JSON.stringify({ type: "session", id: "b", timestamp: "2025-01-01T00:00:00Z", cwd: projectB })}\n`,
		);

		expect(findMostRecentSession(tempDir, projectA)).toBe(fileA);
		expect(findMostRecentSession(tempDir, projectB)).toBe(fileB);
	});
});

