	if (typeof content === "string") return [{ type: "text", text: content }];
	return content.map((part) => {
		switch (part.type) {
			case "text":
				return { type: "text", text: part.text };
			case "image":
				return { type: "image", data: part.data, mimeType: part.mimeType };
			default: {
				const exhaustive: never = part;
				return exhaustive;
			}
		}
	});
}

