/**
 * Interface for custom editor components.
 *
 * This allows extensions to provide their own editor implementation
 * (e.g., vim mode, emacs mode, custom keybindings) while maintaining
 * compatibility with the core application.
 */
export interface EditorComponent extends Component {
	// =========================================================================
	// Core text access (required)
	// =========================================================================

	/** Get the current text content */
	getText(): string;

	/** Set the text content */
	setText(text: string): void;

	/** Handle raw terminal input (key presses, paste sequences, etc.) */
	handleInput(data: string): void;

	// =========================================================================
	// Callbacks (required)
	// =========================================================================

	/** Called when user submits (e.g., Enter key) */
	onSubmit?: (payload: { text: string; attachments: PasteAttachment[] }) => void;

	/** Called when text changes */
	onChange?: (text: string) => void;

	// =========================================================================
	// History support (optional)
	// =========================================================================

	/** Add text to history for up/down navigation */
	addToHistory?(text: string): void;

	// =========================================================================
	// Advanced text manipulation (optional)
	// =========================================================================

	/** Insert text at current cursor position */
	insertTextAtCursor?(text: string): void;

	/**
	 * Get text with any markers expanded (e.g., paste markers).
	 * Falls back to getText() if not implemented.
	 */
	getExpandedText?(): string;

	/**
	 * Get the attachments (text + image) currently behind paste markers.
	 * Returns an empty array if the implementation doesn't support attachments.
	 */
	getAttachments?(): PasteAttachment[];

	/**
	 * Programmatically paste text. Implementations decide whether to store it
	 * inline or behind a paste marker based on size/options.
	 */
	pasteText(text: string, opts?: { forceMarker?: boolean; skipUndoSnapshot?: boolean }): void;

	/**
	 * Programmatically paste an image. Stores the bytes behind a paste marker.
	 */
	pasteImage(bytes: Uint8Array, mimeType: string, fileName: string): void;

	/**
	 * Programmatically paste a video. Stores the bytes behind a paste marker.
	 */
	pasteVideo(bytes: Uint8Array, mimeType: string, fileName: string): void;

	// =========================================================================
	// Autocomplete support (optional)
	// =========================================================================

	/** Set the autocomplete provider */
	setAutocompleteProvider?(provider: AutocompleteProvider): void;

	// =========================================================================
	// Appearance (optional)
	// =========================================================================

	/** Border color function */
	borderColor?: (str: string) => string;

	/** Set horizontal padding */
	setPaddingX?(padding: number): void;

	/** Set max visible items in autocomplete dropdown */
	setAutocompleteMaxVisible?(maxVisible: number): void;
}

